// Class 9 Science practice bank, part 2: motion, force, gravitation, work and energy, sound, food resources.
StudyData.addPractice(9, "science", {
  motion: {
    mcq: [
      { q: "A velocity–time graph is a straight line parallel to the time axis, drawn above it. The body is moving with:", options: ["uniform acceleration", "constant (uniform) velocity", "uniform retardation", "zero velocity"], answer: 1, explain: "The velocity does not change with time, so the acceleration is zero and the velocity is constant.", level: 1 },
      { q: "Which of these quantities is a vector?", options: ["Distance", "Speed", "Time", "Displacement"], answer: 3, explain: "Displacement has both magnitude and direction. Distance, speed and time are scalars.", level: 1 },
      { q: "The SI unit of acceleration is:", options: ["m s⁻¹", "kg m s⁻²", "m s⁻²", "m² s⁻¹"], answer: 2, explain: "Acceleration = change in velocity ÷ time, so its unit is (m s⁻¹) ÷ s = m s⁻².", level: 1 },
      { q: "The odometer of a car measures the:", options: ["distance covered", "displacement", "instantaneous velocity", "acceleration"], answer: 0, explain: "An odometer records the total path length covered, which is distance.", level: 1 },
      { q: "A body is said to be in uniform motion if it covers:", options: ["equal distances in equal intervals of time", "unequal distances in equal intervals of time", "equal distances in unequal intervals of time", "the same displacement in every interval"], answer: 0, explain: "Uniform motion means equal distances in equal intervals of time, however small the intervals are.", level: 1 },

      {
        q: "Assertion (A): A body moving in a circle at constant speed is accelerated.\nReason (R): The direction of its velocity changes continuously.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Velocity is a vector, so a change in direction is a change in velocity, which means acceleration.", level: 2, keepOrder: true
      },
      {
        q: "Assertion (A): A body moving with constant speed always has constant velocity.\nReason (R): Velocity includes direction as well as speed.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "A is false: constant speed on a curved path means the direction, and so the velocity, keeps changing. R is true.", level: 2, keepOrder: true
      },
      { q: "A boy runs at constant speed along a circular track of radius 70 m and completes one round in 40 s. His speed is: (π = 22/7)", options: ["5.5 m s⁻¹", "22 m s⁻¹", "11 m s⁻¹", "0 m s⁻¹"], answer: 2, explain: "v = 2πr ÷ t = 2 × (22/7) × 70 ÷ 40 = 440 ÷ 40 = 11 m s⁻¹.", level: 2 },
      { q: "A cyclist riding at 5 m s⁻¹ sees a red light 25 m ahead and brakes uniformly to stop exactly at the light. The magnitude of the retardation is:", options: ["0.25 m s⁻²", "0.5 m s⁻²", "1 m s⁻²", "2.5 m s⁻²"], answer: 1, explain: "v² = u² + 2as gives 0 = 25 + 2a × 25, so a = −0.5 m s⁻². The retardation is 0.5 m s⁻².", level: 2 },
      { q: "The velocity–time graph of a body is a straight line from the origin to the point (5 s, 20 m s⁻¹). Its displacement in 5 s is:", options: ["100 m", "4 m", "25 m", "50 m"], answer: 3, explain: "Displacement = area of the triangle = ½ × 5 × 20 = 50 m.", level: 2 },

      { q: "A car travels 60 km at a speed of 30 km h⁻¹ and the next 60 km at 60 km h⁻¹. Its average speed for the whole journey is:", options: ["45 km h⁻¹", "40 km h⁻¹", "50 km h⁻¹", "30 km h⁻¹"], answer: 1, explain: "Time = 60/30 + 60/60 = 2 + 1 = 3 h. Average speed = 120 ÷ 3 = 40 km h⁻¹ (not the simple mean 45).", level: 3 },
      { q: "A body starts from rest and accelerates at 2 m s⁻² for 5 s, and then moves with the velocity so gained for the next 10 s. The total distance covered is:", options: ["100 m", "150 m", "125 m", "75 m"], answer: 2, explain: "First 5 s: s = ½ × 2 × 5² = 25 m, and v = 2 × 5 = 10 m s⁻¹. Next 10 s: 10 × 10 = 100 m. Total = 125 m.", level: 3 },
      { q: "A train 200 m long, moving at a uniform speed of 20 m s⁻¹, crosses a bridge 400 m long. The time taken from the engine entering the bridge to the last coach leaving it is:", options: ["30 s", "20 s", "10 s", "15 s"], answer: 0, explain: "Distance to be covered = 200 + 400 = 600 m. Time = 600 ÷ 20 = 30 s.", level: 3 },
      { q: "A body speeds up uniformly from rest to 10 m s⁻¹ in 5 s, moves at 10 m s⁻¹ for the next 5 s, and then slows uniformly to rest in the next 5 s. The total distance covered is:", options: ["150 m", "75 m", "200 m", "100 m"], answer: 3, explain: "Area under the graph: 25 m + 50 m + 25 m = 100 m (a trapezium with parallel sides 15 s and 5 s, height 10 m: ½ × 20 × 10).", level: 3 }
    ],
    written: [
      { q: "Define acceleration and state its SI unit.", a: "Acceleration is the rate of change of velocity with time, a = (v − u) ÷ t. Its SI unit is m s⁻².", marks: 1 },
      { q: "What does the slope of a velocity–time graph represent?", a: "The slope of a velocity–time graph gives the acceleration of the body.", marks: 1 },
      { q: "Distinguish between distance and displacement.", a: "Distance is the total length of the path travelled; it is a scalar and is never zero for a moving body.\nDisplacement is the shortest straight-line distance from the initial to the final position, with direction; it is a vector and can be zero (for example after one full round of a circular track).", marks: 2 },
      { q: "The speedometer of a car reads a steady 60 km h⁻¹ while it goes round a bend. Is its velocity constant? Give a reason.", a: "No, its velocity is not constant.\nSpeed is constant, but the direction of motion changes along the bend, and velocity depends on direction as well as speed, so the car is accelerated.", marks: 2 },
      { q: "A car speeds up uniformly from 18 km h⁻¹ to 54 km h⁻¹ in 5 s. Find its acceleration and the distance it covers in this time.", a: "u = 18 × 5/18 = 5 m s⁻¹; v = 54 × 5/18 = 15 m s⁻¹; t = 5 s\na = (v − u) ÷ t = (15 − 5) ÷ 5 = 2 m s⁻²\ns = ut + ½at² = 5 × 5 + ½ × 2 × 25 = 25 + 25 = 50 m\nAcceleration = 2 m s⁻² and distance = 50 m.", marks: 3 },
      { q: "The distance–time graph of a cyclist consists of three straight parts. OA joins (0 s, 0 m) to (10 s, 40 m); AB is parallel to the time axis from 10 s to 20 s; BC joins (20 s, 40 m) to (30 s, 100 m). Find the speed in each part and the average speed for the whole 30 s.", a: "Speed = slope of the distance–time graph.\nOA: 40 ÷ 10 = 4 m s⁻¹\nAB: the graph is horizontal, so the cyclist is at rest; speed = 0\nBC: (100 − 40) ÷ (30 − 20) = 6 m s⁻¹\nAverage speed = total distance ÷ total time = 100 ÷ 30 ≈ 3.33 m s⁻¹.", marks: 3 },
      { q: "An athlete runs at constant speed and completes 2 rounds of a circular track of radius 35 m in 44 s. (Take π = 22/7.) Find (i) his speed and (ii) his displacement at the end of 44 s. (iii) Why is his motion accelerated?", a: "Circumference = 2πr = 2 × 22/7 × 35 = 220 m\n(i) Distance in 2 rounds = 440 m, so speed = 440 ÷ 44 = 10 m s⁻¹.\n(ii) He is back at the starting point, so the displacement is zero.\n(iii) The direction of his velocity changes continuously, so the velocity changes and the motion is accelerated.", marks: 3 },
      { q: "Derive the equation s = ut + ½at² using a velocity–time graph.", a: "Let a body start with velocity u and move with uniform acceleration a, reaching velocity v in time t.\nIn the velocity–time graph the velocity rises in a straight line from u to v. The displacement s is the area under the graph, a trapezium.\n1. The area splits into a rectangle of height u and base t, and a triangle of height (v − u) and base t.\n2. Rectangle area = u × t.\n3. Triangle area = ½ × t × (v − u).\n4. From a = (v − u) ÷ t, we get (v − u) = at, so the triangle area = ½ × t × at = ½at².\n5. Adding: s = ut + ½at².", marks: 5 },
      { q: "A body starts from rest. Its velocity–time graph is a straight line from (0 s, 0) to (10 s, 20 m s⁻¹), then a horizontal line up to 30 s, then a straight line falling to zero at 40 s. Find (i) the acceleration in the first 10 s, (ii) the acceleration from 10 s to 30 s, (iii) the retardation in the last 10 s and (iv) the total distance covered.", a: "Acceleration = slope of the velocity–time graph; distance = area under it.\n(i) a = (20 − 0) ÷ 10 = 2 m s⁻²\n(ii) The graph is horizontal, so a = 0 (uniform velocity of 20 m s⁻¹).\n(iii) a = (0 − 20) ÷ 10 = −2 m s⁻², a retardation of 2 m s⁻².\n(iv) Distance = ½ × 10 × 20 + 20 × 20 + ½ × 10 × 20 = 100 + 400 + 100 = 600 m.", marks: 5 },
      {
        q: "Case study: A car starts from rest, and its speedometer is read every 5 s. The readings are 0 m s⁻¹ at 0 s, 10 m s⁻¹ at 5 s, 20 m s⁻¹ at 10 s and 30 m s⁻¹ at 15 s.\n(i) What type of motion is this?\n(ii) Find the acceleration of the car.\n(iii) Find the distance covered in the 15 s.",
        a: "(i) The velocity increases by equal amounts (10 m s⁻¹) in equal intervals (5 s), so it is motion with uniform acceleration.\n(ii) a = (30 − 0) ÷ 15 = 2 m s⁻².\n(iii) s = ut + ½at² = 0 + ½ × 2 × 15² = 225 m.",
        marks: 4, type: "case"
      }
    ]
  }
,
  "force-and-laws-of-motion": {
    mcq: [
      { q: "Newton's first law of motion is also known as the:", options: ["law of acceleration", "law of inertia", "law of momentum", "law of gravitation"], answer: 1, explain: "The first law describes inertia, the tendency of a body to keep its state of rest or uniform motion.", level: 1 },
      { q: "One newton is equal to:", options: ["1 kg m s⁻¹", "1 kg m² s⁻²", "1 kg m s⁻²", "1 g cm s⁻²"], answer: 2, explain: "F = ma, so 1 N = 1 kg × 1 m s⁻² = 1 kg m s⁻².", level: 1 },
      { q: "The quantity that measures the inertia of a body is its:", options: ["weight", "force", "momentum", "mass"], answer: 3, explain: "The larger the mass, the greater the inertia, so mass is the measure of inertia.", level: 1 },
      { q: "Passengers in a stationary bus fall backward when the bus suddenly starts. This is due to:", options: ["inertia of rest", "inertia of motion", "friction between the seat and the passenger", "the action–reaction law"], answer: 0, explain: "The lower body moves with the bus but the upper body tends to stay at rest, so passengers fall backward.", level: 1 },
      { q: "If no external unbalanced force acts on a system, its total momentum:", options: ["keeps increasing", "keeps decreasing", "remains constant", "becomes zero"], answer: 2, explain: "This is the law of conservation of momentum.", level: 1 },

      {
        q: "Assertion (A): A cricketer moves his hands backward while catching a fast ball.\nReason (R): The longer time taken to stop the ball reduces the force exerted on his hands.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "F = change in momentum ÷ time. The change in momentum is fixed, so a larger time gives a smaller force.", level: 2, keepOrder: true
      },
      {
        q: "Assertion (A): The action and reaction forces do not cancel each other.\nReason (R): The action and reaction forces are equal in magnitude.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 1, explain: "Both are true, but they do not cancel because they act on two different bodies, not because of their magnitudes.", level: 2, keepOrder: true
      },
      { q: "A boy of mass 40 kg running at 6 m s⁻¹ jumps onto a stationary trolley of mass 20 kg, and they move off together. Their common velocity is:", options: ["6 m s⁻¹", "2 m s⁻¹", "3 m s⁻¹", "4 m s⁻¹"], answer: 3, explain: "40 × 6 = (40 + 20) × v, so v = 240 ÷ 60 = 4 m s⁻¹.", level: 2 },
      { q: "Ravi gives the same push to an empty shopping trolley and then to the same trolley full of groceries. The loaded trolley speeds up less because:", options: ["its weight is smaller", "its mass is greater, so a = F ÷ m is smaller", "the push on it is smaller", "friction does not act on the empty trolley"], answer: 1, explain: "For the same force, acceleration is inversely proportional to mass.", level: 2 },
      { q: "A 0.2 kg ball moving at 15 m s⁻¹ is caught and brought to rest by a fielder in 0.1 s. The average force exerted by the hands is:", options: ["300 N", "3 N", "30 N", "1.5 N"], answer: 2, explain: "F = m(v − u) ÷ t = 0.2 × (0 − 15) ÷ 0.1 = −30 N, a force of 30 N opposing the ball.", level: 2 },

      { q: "A gun of mass 3 kg fires a bullet of mass 10 g at 300 m s⁻¹. The recoil speed of the gun is:", options: ["0.1 m s⁻¹", "1 m s⁻¹", "10 m s⁻¹", "0.01 m s⁻¹"], answer: 1, explain: "0 = 0.01 × 300 + 3V gives V = −1 m s⁻¹, so the recoil speed is 1 m s⁻¹.", level: 3 },
      { q: "A 4 kg block moving at 5 m s⁻¹ hits a 6 kg block moving at 2 m s⁻¹ in the same direction. They stick together. Their common velocity is:", options: ["3.5 m s⁻¹", "3.0 m s⁻¹", "2.8 m s⁻¹", "3.2 m s⁻¹"], answer: 3, explain: "Momentum before = 4 × 5 + 6 × 2 = 32 kg m s⁻¹. v = 32 ÷ (4 + 6) = 3.2 m s⁻¹.", level: 3 },
      { q: "A constant force of 10 N acts for 2 s on a body of mass 5 kg that is initially at rest. Its final velocity is:", options: ["4 m s⁻¹", "2 m s⁻¹", "10 m s⁻¹", "20 m s⁻¹"], answer: 0, explain: "Change in momentum = F × t = 20 kg m s⁻¹, so v = 20 ÷ 5 = 4 m s⁻¹.", level: 3 },
      { q: "A horse pulls a cart, and the cart pulls the horse back with an equal force. Yet the cart moves forward. This is because:", options: ["the horse pulls the cart harder than the cart pulls the horse", "action and reaction act on the same body", "the ground pushes the horse forward with a force larger than the friction on the cart, so a net force acts on the system", "the cart has no inertia"], answer: 2, explain: "The pair of forces acts on different bodies. The horse pushes the ground backward and the ground pushes it forward; this forward force exceeds the friction opposing the cart, so the system accelerates.", level: 3 }
    ],
    written: [
      { q: "Define one newton of force.", a: "One newton is the force that produces an acceleration of 1 m s⁻² in an object of mass 1 kg; 1 N = 1 kg m s⁻².", marks: 1 },
      { q: "State the law of conservation of momentum.", a: "The total momentum of an isolated system (no external unbalanced force) remains constant; the total momentum before a collision equals the total momentum after it.", marks: 1 },
      { q: "A coin rests on a card placed over a glass. When the card is flicked sharply, the coin drops into the glass. Explain.", a: "The coin is at rest and tends to stay at rest because of its inertia.\nThe card moves away quickly, so the coin does not move sideways with it and falls straight down into the glass under gravity.", marks: 2 },
      { q: "A ball rolling on level ground slowly comes to rest. Does this contradict Newton's first law? Explain.", a: "No, it does not contradict the first law.\nThe law says a body keeps moving uniformly unless an unbalanced force acts. Here friction (and air resistance) is the unbalanced force that opposes the motion and stops the ball.", marks: 2 },
      { q: "A force of 40 N acts on a body of mass 10 kg, initially at rest, for 5 s. Find (i) the acceleration, (ii) the final velocity and (iii) the distance travelled in this time.", a: "(i) a = F ÷ m = 40 ÷ 10 = 4 m s⁻²\n(ii) v = u + at = 0 + 4 × 5 = 20 m s⁻¹\n(iii) s = ut + ½at² = 0 + ½ × 4 × 25 = 50 m", marks: 3 },
      { q: "A gun of mass 4 kg fires a bullet of mass 50 g at a speed of 200 m s⁻¹. Find (i) the recoil velocity of the gun and (ii) the momentum of the bullet and of the gun after firing.", a: "Momentum before firing = 0.\n(i) 0.05 × 200 + 4 × V = 0, so 10 + 4V = 0 and V = −2.5 m s⁻¹. The gun recoils at 2.5 m s⁻¹ opposite to the bullet.\n(ii) Momentum of the bullet = 0.05 × 200 = 10 kg m s⁻¹ forward; momentum of the gun = 4 × 2.5 = 10 kg m s⁻¹ backward. They are equal and opposite, so the total stays zero.", marks: 3 },
      { q: "A truck of mass 3000 kg moving at 10 m s⁻¹ collides with a stationary car of mass 1000 kg, and the two move together after the collision. Find their common velocity and show that momentum is conserved.", a: "Momentum before = 3000 × 10 + 1000 × 0 = 30000 kg m s⁻¹\nLet the common velocity be v: (3000 + 1000) × v = 30000\nv = 30000 ÷ 4000 = 7.5 m s⁻¹\nMomentum after = 4000 × 7.5 = 30000 kg m s⁻¹, equal to the momentum before, so momentum is conserved.", marks: 3 },
      { q: "State Newton's second law of motion and use it to derive the relation F = ma.", a: "Second law: the rate of change of momentum of a body is directly proportional to the applied unbalanced force and takes place in the direction of the force.\n1. Let a body of mass m change its velocity from u to v in time t. Initial momentum = mu, final momentum = mv.\n2. Rate of change of momentum = (mv − mu) ÷ t = m(v − u) ÷ t.\n3. So F ∝ m(v − u) ÷ t, or F = k m(v − u) ÷ t, where k is a constant.\n4. Since (v − u) ÷ t = a, F = k m a.\n5. The unit of force is defined so that k = 1 (1 N produces 1 m s⁻² in 1 kg). Hence F = ma.", marks: 5 },
      { q: "Two balls A and B of masses mA and mB move in the same direction with velocities uA and uB (uA > uB). They collide for a time t, and their velocities become vA and vB. Use Newton's second and third laws to prove the law of conservation of momentum.", a: "1. Force on B by A: F(A on B) = mB(vB − uB) ÷ t (second law).\n2. Force on A by B: F(B on A) = mA(vA − uA) ÷ t (second law).\n3. By the third law, F(A on B) = −F(B on A).\n4. So mB(vB − uB) ÷ t = −mA(vA − uA) ÷ t, which gives mB(vB − uB) = −mA(vA − uA).\n5. Rearranging: mAuA + mBuB = mAvA + mBvB.\nThus the total momentum before the collision equals the total momentum after it.", marks: 5 },
      {
        q: "Case study: A car of mass 1500 kg moving at 20 m s⁻¹ is brought to rest uniformly in 5 s after the driver applies the brakes. A passenger of mass 60 kg in the car is not wearing a seat belt.\n(i) Find the retardation of the car.\n(ii) Find the average braking force on the car.\n(iii) Which law explains why the passenger is thrown forward, and what force would a seat belt have to apply to stop him with the car?",
        a: "(i) a = (v − u) ÷ t = (0 − 20) ÷ 5 = −4 m s⁻², a retardation of 4 m s⁻².\n(ii) F = ma = 1500 × 4 = 6000 N, opposite to the direction of motion.\n(iii) Newton's first law (inertia of motion): the passenger tends to keep moving forward at 20 m s⁻¹ while the car stops. To stop him with the car the belt must supply F = 60 × 4 = 240 N.",
        marks: 4, type: "case"
      }
    ]
  }
,
  gravitation: {
    mcq: [
      { q: "The SI unit of the universal gravitation constant G is:", options: ["N m² kg⁻²", "N kg² m⁻²", "N m kg⁻¹", "N m⁻² kg²"], answer: 0, explain: "From F = Gm₁m₂ ÷ d², G = F d² ÷ (m₁m₂), whose unit is N m² kg⁻².", level: 1 },
      { q: "The force that keeps the Moon in its orbit around the Earth is:", options: ["magnetic force", "gravitational force", "frictional force", "nuclear force"], answer: 1, explain: "The gravitational attraction of the Earth provides the force that keeps the Moon in its orbit.", level: 1 },
      { q: "The SI unit of pressure is:", options: ["newton", "joule", "pascal", "watt"], answer: 2, explain: "Pressure = thrust ÷ area, and 1 pascal = 1 N m⁻².", level: 1 },
      { q: "The weight of an object can be measured directly with a:", options: ["beam balance using standard masses", "spring balance", "stopwatch", "barometer"], answer: 1, explain: "A spring balance measures the force (weight) pulling the body down; its reading is in newtons.", level: 1 },
      { q: "According to Archimedes' principle, the upward force on a body immersed in a fluid equals:", options: ["the weight of the body", "the volume of the body", "the mass of the fluid in the container", "the weight of the fluid displaced by the body"], answer: 3, explain: "The buoyant force equals the weight of the fluid displaced.", level: 1 },

      {
        q: "Assertion (A): The weight of an object on the Moon is less than its weight on the Earth.\nReason (R): The mass of the object is less on the Moon.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 2, explain: "A is true because the Moon's gravity is weaker. R is false: mass does not change from place to place.", level: 2, keepOrder: true
      },
      {
        q: "Assertion (A): In a vacuum, a heavy stone and a light stone dropped from the same height reach the ground together.\nReason (R): The acceleration due to gravity does not depend on the mass of the falling body.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Both fall with the same acceleration g, so they take the same time.", level: 2, keepOrder: true
      },
      { q: "A girl weighing 400 N stands on one foot whose area of contact with the ground is 200 cm². The pressure she exerts on the ground is:", options: ["2000 Pa", "8000 Pa", "200 Pa", "20000 Pa"], answer: 3, explain: "Area = 200 cm² = 0.02 m². Pressure = 400 ÷ 0.02 = 20000 Pa.", level: 2 },
      { q: "A student has a wax piece of density 0.9 g cm⁻³. Water has density 1.0 g cm⁻³ and kerosene 0.8 g cm⁻³. The wax will:", options: ["sink in water and float in kerosene", "float in water and sink in kerosene", "float in both", "sink in both"], answer: 1, explain: "A body floats in a liquid of greater density and sinks in a liquid of lower density.", level: 2 },
      { q: "If the mass of one body is doubled and the distance between the two bodies is tripled, the gravitational force between them becomes:", options: ["6 times", "2/3 times", "9/2 times", "2/9 times"], answer: 3, explain: "F ∝ m₁m₂ ÷ d², so the new force = 2 ÷ 3² = 2/9 of the original.", level: 2 },

      { q: "A stone dropped from the top of a tower reaches the ground in 3 s. The height of the tower is: (g = 9.8 m s⁻²)", options: ["44.1 m", "29.4 m", "88.2 m", "14.7 m"], answer: 0, explain: "h = ½gt² = ½ × 9.8 × 3² = 44.1 m.", level: 3 },
      { q: "A ball is thrown vertically upward at 20 m s⁻¹. Taking g = 10 m s⁻², its speed on returning to the thrower's hand and the total time of flight are:", options: ["20 m s⁻¹, 2 s", "0 m s⁻¹, 4 s", "20 m s⁻¹, 4 s", "10 m s⁻¹, 2 s"], answer: 2, explain: "Time to rise = 20 ÷ 10 = 2 s, so total time = 4 s. By symmetry it returns with the same speed, 20 m s⁻¹.", level: 3 },
      { q: "A rectangular block with edges 20 cm, 10 cm and 5 cm is placed on a table first on its largest face and then on its smallest face. The ratio of the pressures (smallest face : largest face) is:", options: ["1 : 4", "4 : 1", "2 : 1", "1 : 1"], answer: 1, explain: "Largest face = 200 cm², smallest face = 50 cm². Pressure is inversely proportional to area, so the ratio is 200 : 50 = 4 : 1.", level: 3 },
      { q: "A man can exert a force that lifts at most 90 kg on the Earth. If the Moon's gravity is 1/6 that of the Earth, the maximum mass he can lift on the Moon is:", options: ["15 kg", "90 kg", "540 kg", "1080 kg"], answer: 2, explain: "His maximum force is the weight of 90 kg on the Earth. On the Moon the same force balances a mass six times larger: 90 × 6 = 540 kg.", level: 3 }
    ],
    written: [
      { q: "State Archimedes' principle.", a: "When a body is immersed fully or partially in a fluid, it experiences an upward force (buoyant force) equal to the weight of the fluid displaced by it.", marks: 1 },
      { q: "What is meant by free fall?", a: "Free fall is the motion of a body falling towards the Earth under the action of gravitational force alone (no air resistance); its acceleration is g = 9.8 m s⁻².", marks: 1 },
      { q: "Distinguish between mass and weight (any two points).", a: "Mass is the quantity of matter in a body, is constant everywhere, and its SI unit is kg.\nWeight is the force with which the Earth attracts the body (W = mg), changes from place to place, and its SI unit is the newton.", marks: 2 },
      { q: "An iron nail sinks in water but a huge iron ship floats. Explain.", a: "The nail's density is greater than that of water, so the weight of the water it displaces is less than its own weight and it sinks.\nThe ship's hull is shaped to displace a very large volume of water; its average density (including the air inside) is less than that of water, so the buoyant force balances its weight and it floats.", marks: 2 },
      { q: "Calculate the gravitational force between two bodies of masses 50 kg and 100 kg placed 5 m apart. By what factor does the force change if the distance is halved? (G = 6.67 × 10⁻¹¹ N m² kg⁻²)", a: "F = G m₁m₂ ÷ d² = 6.67 × 10⁻¹¹ × 50 × 100 ÷ 5²\n= 6.67 × 10⁻¹¹ × 5000 ÷ 25 = 6.67 × 10⁻¹¹ × 200\n= 1.334 × 10⁻⁸ N\nHalving the distance makes d² one-fourth, so the force becomes 4 times: 5.34 × 10⁻⁸ N.", marks: 3 },
      { q: "A ball is dropped from the top of an 80 m high building. Taking g = 10 m s⁻², find (i) the time it takes to reach the ground, (ii) its speed just before hitting the ground and (iii) the distance it falls in the first 2 s.", a: "u = 0, a = g = 10 m s⁻², h = 80 m\n(i) h = ½gt², so 80 = 5t², t² = 16 and t = 4 s.\n(ii) v = u + gt = 0 + 10 × 4 = 40 m s⁻¹.\n(iii) h = ½ × 10 × 2² = 20 m.", marks: 3 },
      { q: "A boy of mass 45 kg stands on a floor, first on both feet (total contact area 300 cm²) and then on one foot (150 cm²). Find the pressure on the floor in each case. (g = 10 m s⁻²)", a: "Thrust = weight = mg = 45 × 10 = 450 N\nBoth feet: area = 300 cm² = 0.03 m², pressure = 450 ÷ 0.03 = 15000 Pa\nOne foot: area = 150 cm² = 0.015 m², pressure = 450 ÷ 0.015 = 30000 Pa\nThe pressure doubles because the same thrust acts on half the area.", marks: 3 },
      { q: "State the universal law of gravitation and write its mathematical form, naming each symbol. Give the SI unit of G. How does the force change if the distance between the bodies is doubled? Why do we not notice the gravitational attraction between everyday objects?", a: "1. Law: every object in the universe attracts every other object with a force directly proportional to the product of their masses and inversely proportional to the square of the distance between them.\n2. F = G m₁m₂ ÷ d², where m₁ and m₂ are the masses, d is the distance between them and G is the universal gravitation constant.\n3. SI unit of G is N m² kg⁻² (G = 6.67 × 10⁻¹¹ N m² kg⁻²).\n4. If d is doubled, the force becomes one-fourth.\n5. G is extremely small, so the force between ordinary objects is far too tiny to notice; it becomes large only when at least one mass is huge, like the Earth.", marks: 5 },
      { q: "A stone is thrown vertically upward with a speed of 29.4 m s⁻¹. Taking g = 9.8 m s⁻², find (i) the maximum height reached, (ii) the time taken to reach it, (iii) the total time before it returns to the thrower, (iv) its speed on return and (v) its height after 2 s.", a: "Upward motion: u = 29.4 m s⁻¹, a = −9.8 m s⁻²; at the top v = 0.\n(i) v² = u² + 2as: 0 = 29.4² − 2 × 9.8 × h, so h = 864.36 ÷ 19.6 = 44.1 m.\n(ii) v = u + at: 0 = 29.4 − 9.8t, so t = 3 s.\n(iii) The fall takes equally long, so the total time = 6 s.\n(iv) It returns with the same speed, 29.4 m s⁻¹ (directed downward).\n(v) s = ut + ½at² = 29.4 × 2 − ½ × 9.8 × 4 = 58.8 − 19.6 = 39.2 m.", marks: 5 },
      {
        q: "Case study: In a school laboratory, Asha hangs a solid iron ball from a spring balance. It reads 5 N in air. When she lowers the ball fully into water, the reading falls to 4 N.\n(i) Find the buoyant force on the ball.\n(ii) What is the weight of the water displaced?\n(iii) Will the ball float if released in water? Give a reason.",
        a: "(i) Buoyant force = loss in apparent weight = 5 − 4 = 1 N, acting upward.\n(ii) By Archimedes' principle the weight of the water displaced = buoyant force = 1 N.\n(iii) No, it will sink. Its weight (5 N) is greater than the largest buoyant force it can get (1 N), because iron is denser than water.",
        marks: 4, type: "case"
      }
    ]
  }
,
  "work-and-energy": {
    mcq: [
      { q: "The work done by a force that acts perpendicular to the displacement of the body is:", options: ["maximum", "zero", "negative", "equal to F × s"], answer: 1, explain: "Work is done only by the component of force along the displacement. A perpendicular force has no such component.", level: 1 },
      { q: "The SI unit of energy is the:", options: ["watt", "newton", "pascal", "joule"], answer: 3, explain: "Energy and work are both measured in joules (1 J = 1 N m).", level: 1 },
      { q: "A stretched rubber band has:", options: ["kinetic energy", "potential energy", "sound energy", "no energy"], answer: 1, explain: "Energy stored because of a change in shape is potential energy.", level: 1 },
      { q: "In a hydroelectric power plant the sequence of energy changes is:", options: ["potential energy of water → kinetic energy → electrical energy", "electrical energy → potential energy of water → kinetic energy", "chemical energy → heat → electrical energy", "heat energy → kinetic energy → electrical energy"], answer: 0, explain: "Water stored at a height has potential energy; falling water gains kinetic energy and turns the turbine to produce electrical energy.", level: 1 },
      { q: "Power is:", options: ["work × time", "force × distance", "the rate of doing work", "energy ÷ mass"], answer: 2, explain: "P = W ÷ t, the work done per unit time.", level: 1 },

      {
        q: "Assertion (A): A porter walking on level ground with a suitcase on his head does no work against gravity on the suitcase.\nReason (R): The weight of the suitcase acts perpendicular to its displacement.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "The force of gravity is vertical and the displacement is horizontal, so the work done by (or against) gravity is zero.", level: 2, keepOrder: true
      },
      {
        q: "Assertion (A): The kinetic energy of a body becomes four times when its speed is doubled.\nReason (R): The kinetic energy of a body is directly proportional to its speed.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 2, explain: "Eₖ = ½mv² is proportional to v², so A is true; R is false because Eₖ is not proportional to v.", level: 2, keepOrder: true
      },
      { q: "A family runs a 2 kW geyser for 30 minutes and a 100 W fan for 10 hours in a day. The total electrical energy used is:", options: ["1 kW h", "3 kW h", "12 kW h", "2 kW h"], answer: 3, explain: "Geyser: 2 kW × 0.5 h = 1 kW h. Fan: 0.1 kW × 10 h = 1 kW h. Total = 2 kW h.", level: 2 },
      { q: "A pendulum bob is released from its highest point and swings down to its lowest point. At the lowest point, the bob has:", options: ["zero kinetic energy and maximum potential energy", "zero kinetic and zero potential energy", "maximum kinetic energy and minimum potential energy", "maximum potential and maximum kinetic energy"], answer: 2, explain: "The potential energy at the top has been converted into kinetic energy, so KE is maximum and PE is minimum at the lowest point.", level: 2 },
      { q: "The kinetic energy of a 2 kg body moving at 36 km h⁻¹ is:", options: ["100 J", "36 J", "1296 J", "72 J"], answer: 0, explain: "36 km h⁻¹ = 10 m s⁻¹. Eₖ = ½ × 2 × 10² = 100 J.", level: 2 },

      { q: "A 0.5 kg ball is dropped from a height of 20 m. Ignoring air resistance (g = 10 m s⁻²), its kinetic energy when it is 15 m above the ground is:", options: ["75 J", "100 J", "50 J", "25 J"], answer: 3, explain: "Total energy = mgh = 0.5 × 10 × 20 = 100 J. PE at 15 m = 0.5 × 10 × 15 = 75 J, so KE = 100 − 75 = 25 J.", level: 3 },
      { q: "A pump raises 600 kg of water every minute from a well 20 m deep. The power of the pump is: (g = 10 m s⁻²)", options: ["200 W", "1200 W", "2000 W", "12000 W"], answer: 2, explain: "Work per minute = mgh = 600 × 10 × 20 = 120000 J. Power = 120000 ÷ 60 = 2000 W.", level: 3 },
      { q: "The speed of a 2 kg body changes from 10 m s⁻¹ to 20 m s⁻¹. The work done on it is:", options: ["100 J", "300 J", "400 J", "200 J"], answer: 1, explain: "Work = change in KE = ½ × 2 × (20² − 10²) = 400 − 100 = 300 J.", level: 3 },
      { q: "Two bodies of masses in the ratio 1 : 4 have equal kinetic energies. The ratio of their speeds is:", options: ["2 : 1", "1 : 2", "4 : 1", "1 : 4"], answer: 0, explain: "½m₁v₁² = ½m₂v₂² gives v₁² ÷ v₂² = m₂ ÷ m₁ = 4, so v₁ : v₂ = 2 : 1.", level: 3 }
    ],
    written: [
      { q: "Define one joule of work.", a: "One joule is the work done when a force of 1 newton moves an object through a distance of 1 metre in the direction of the force; 1 J = 1 N m.", marks: 1 },
      { q: "State the law of conservation of energy.", a: "Energy can neither be created nor destroyed; it can only be changed from one form to another, and the total energy remains constant.", marks: 1 },
      { q: "Give two situations in which a force acts on a body but no work is done, with the reason.", a: "1. A person pushing hard against a rigid wall: the force acts but the wall has no displacement.\n2. A satellite moving in a circular orbit, or a porter carrying a load on level ground: the force of gravity is perpendicular to the displacement, so the work done by it is zero.", marks: 2 },
      { q: "A ball is thrown vertically upward. Describe the changes in its kinetic and potential energy as it rises and then falls.", a: "While rising, its speed decreases, so kinetic energy decreases and potential energy increases; at the highest point KE is zero and PE is maximum.\nWhile falling, PE decreases and KE increases. The sum KE + PE stays constant if air resistance is ignored.", marks: 2 },
      { q: "A body of mass 2 kg is dropped from a height of 5 m. Taking g = 10 m s⁻², find (i) its potential energy at the top, (ii) its kinetic energy after it has fallen 2 m and (iii) its speed just before it hits the ground.", a: "(i) PE at top = mgh = 2 × 10 × 5 = 100 J.\n(ii) KE gained = loss of PE = mg × 2 = 2 × 10 × 2 = 40 J.\n(iii) At the ground all PE is converted to KE: ½ × 2 × v² = 100, so v² = 100 and v = 10 m s⁻¹.", marks: 3 },
      { q: "A crane lifts a load of 500 kg through a height of 12 m in 20 s. Find the work done and the power of the crane. (g = 10 m s⁻²)", a: "Work done W = mgh = 500 × 10 × 12 = 60000 J\nPower P = W ÷ t = 60000 ÷ 20 = 3000 W (3 kW)", marks: 3 },
      { q: "In a house, three bulbs of 60 W each are used for 5 hours daily and a 1500 W heater is used for 1 hour daily. Find the total electrical energy used in 30 days in kW h, and the bill at ₹6 per unit.", a: "Daily energy of bulbs = 3 × 0.06 kW × 5 h = 0.9 kW h\nDaily energy of heater = 1.5 kW × 1 h = 1.5 kW h\nTotal per day = 2.4 kW h\nIn 30 days = 2.4 × 30 = 72 kW h (72 units)\nBill = 72 × 6 = ₹432.", marks: 3 },
      { q: "Derive the expression for the kinetic energy of a body of mass m moving with velocity v, using the work done to bring it from rest to that velocity.", a: "1. Let a body of mass m at rest be given a constant force F, so that it acquires velocity v after covering a distance s.\n2. Kinetic energy gained = work done by the force = F × s.\n3. From Newton's second law, F = ma.\n4. From the equation of motion with u = 0: v² = 2as, so s = v² ÷ 2a.\n5. Work done W = F × s = ma × v² ÷ (2a) = ½mv².\nSo the kinetic energy is Eₖ = ½mv².", marks: 5 },
      { q: "Show that the sum of kinetic and potential energy of a freely falling body of mass m, dropped from a height h, is the same at the top, after falling a distance x, and at the ground. (Ignore air resistance.)", a: "1. At the top: speed = 0, so KE = 0 and PE = mgh. Total = mgh.\n2. After falling a distance x: v² = 2gx (u = 0), so KE = ½mv² = mgx.\n3. Its height is now (h − x), so PE = mg(h − x).\n4. Total = mgx + mg(h − x) = mgh.\n5. At the ground (x = h): PE = 0 and KE = ½mv² = mgh, so the total is again mgh.\nThe total energy is mgh at every point; the energy only changes from potential to kinetic.", marks: 5 },
      {
        q: "Case study: A roller-coaster car of mass 400 kg is released from rest at the top of a smooth track 20 m high. Ignore friction and take g = 10 m s⁻².\n(i) Find the potential energy of the car at the top.\n(ii) Find its speed at the bottom of the track.\n(iii) Find its kinetic energy when it is 5 m above the bottom.",
        a: "(i) PE = mgh = 400 × 10 × 20 = 80000 J.\n(ii) At the bottom all PE becomes KE: ½ × 400 × v² = 80000, so v² = 400 and v = 20 m s⁻¹.\n(iii) At 5 m, PE = 400 × 10 × 5 = 20000 J. By conservation of energy KE = 80000 − 20000 = 60000 J.",
        marks: 4, type: "case"
      }
    ]
  }
,
  sound: {
    mcq: [
      { q: "The SI unit of frequency is:", options: ["metre", "m s⁻¹", "hertz", "second"], answer: 2, explain: "Frequency is the number of oscillations per second; 1 hertz = 1 oscillation per second.", level: 1 },
      { q: "A region of a sound wave where the pressure and density of the medium are high is called a:", options: ["rarefaction", "compression", "crest", "trough"], answer: 1, explain: "Compressions are high-pressure regions; rarefactions are low-pressure regions.", level: 1 },
      { q: "SONAR makes use of:", options: ["ultrasonic waves", "infrasonic waves", "radio waves", "microwaves"], answer: 0, explain: "SONAR sends ultrasonic waves and detects their echo.", level: 1 },
      { q: "The loudness of a sound depends mainly on the:", options: ["frequency", "wavelength", "amplitude", "speed of the wave"], answer: 2, explain: "A larger amplitude of vibration gives a louder sound.", level: 1 },
      { q: "Sound cannot travel through:", options: ["water", "vacuum", "steel", "air"], answer: 1, explain: "Sound needs a material medium and cannot travel through vacuum.", level: 1 },

      {
        q: "Assertion (A): We see lightning before we hear thunder.\nReason (R): The speed of light is much greater than the speed of sound.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Both are produced together, but light reaches us almost instantly while sound takes longer.", level: 2, keepOrder: true
      },
      {
        q: "Assertion (A): A sound of larger amplitude has a higher pitch.\nReason (R): The pitch of a sound depends on its frequency.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "Larger amplitude gives greater loudness, not higher pitch. Pitch depends on frequency, so R is true and A is false.", level: 2, keepOrder: true
      },
      { q: "A ship's SONAR receives the echo from the seabed 0.4 s after sending a pulse. If the speed of sound in sea water is 1500 m s⁻¹, the depth of the sea is:", options: ["600 m", "300 m", "150 m", "3750 m"], answer: 1, explain: "2d = v × t = 1500 × 0.4 = 600 m, so d = 300 m.", level: 2 },
      { q: "An empty newly built hall has a speaker whose words sound blurred because the sound persists after being reflected many times. The phenomenon and a suitable remedy are:", options: ["echo; make the walls smoother", "reverberation; make the walls hard and polished", "reverberation; use curtains and rough, sound-absorbing wall panels", "echo; remove the ceiling"], answer: 2, explain: "Persistence of sound due to repeated reflection is reverberation. It is reduced by sound-absorbing materials such as curtains and fibreboard.", level: 2 },
      { q: "The time period of a sound wave of frequency 250 Hz is:", options: ["0.004 s", "0.25 s", "4 s", "0.04 s"], answer: 0, explain: "T = 1 ÷ ν = 1 ÷ 250 = 0.004 s.", level: 2 },

      { q: "A man stands between two parallel cliffs and claps. He hears the first echo after 2 s and the second after 3 s. If the speed of sound is 340 m s⁻¹, the distance between the cliffs is:", options: ["170 m", "510 m", "850 m", "1700 m"], answer: 2, explain: "Distance to the nearer cliff = 340 × 2 ÷ 2 = 340 m; to the farther cliff = 340 × 3 ÷ 2 = 510 m. Total = 850 m.", level: 3 },
      { q: "A sound of frequency 500 Hz in air (speed 340 m s⁻¹, wavelength 0.68 m) enters water, where its speed is 1500 m s⁻¹. Its wavelength in water is:", options: ["0.68 m", "3 m", "1500 m", "0.33 m"], answer: 1, explain: "Frequency does not change when sound enters another medium. λ = v ÷ ν = 1500 ÷ 500 = 3 m.", level: 3 },
      { q: "Thunder is heard 5 s after a lightning flash is seen. Taking the speed of sound as 340 m s⁻¹ and treating the light as instantaneous, the lightning struck at a distance of about:", options: ["1700 m", "68 m", "340 m", "1360 m"], answer: 0, explain: "Distance = speed × time = 340 × 5 = 1700 m. (No halving, since the sound travels one way.)", level: 3 },
      { q: "A bat emits an ultrasonic pulse and hears its echo from a wall 0.04 s later. If the speed of sound in air is 340 m s⁻¹, the wall is at a distance of:", options: ["3.4 m", "13.6 m", "68 m", "6.8 m"], answer: 3, explain: "2d = 340 × 0.04 = 13.6 m, so d = 6.8 m.", level: 3 }
    ],
    written: [
      { q: "Define the frequency of a sound wave and state its SI unit.", a: "Frequency is the number of complete oscillations (or waves) produced per second. Its SI unit is the hertz (Hz).", marks: 1 },
      { q: "What is reverberation?", a: "Reverberation is the persistence of sound in a large hall caused by repeated reflections from the walls, ceiling and floor.", marks: 1 },
      { q: "Distinguish between a longitudinal wave and a transverse wave.", a: "In a longitudinal wave the particles of the medium vibrate parallel to the direction of travel of the wave; it forms compressions and rarefactions (for example sound).\nIn a transverse wave the particles vibrate perpendicular to the direction of travel (for example a wave on a slinky moved up and down).", marks: 2 },
      { q: "Distinguish between pitch and loudness of a sound.", a: "Pitch is the sensation of shrillness and depends on the frequency of the sound; a higher frequency gives a higher pitch.\nLoudness depends on the amplitude of vibration; a larger amplitude gives a louder sound.", marks: 2 },
      { q: "The SONAR on a ship receives an echo from a submarine 2 s after sending a pulse. A little later the echo comes back after 1.6 s. If the speed of sound in sea water is 1500 m s⁻¹, find the two distances and say whether the submarine is moving closer or away.", a: "2d = v × t, so d = v × t ÷ 2.\nFirst distance = 1500 × 2 ÷ 2 = 1500 m.\nSecond distance = 1500 × 1.6 ÷ 2 = 1200 m.\nThe distance has decreased, so the submarine is moving closer to the ship.", marks: 3 },
      { q: "A sound wave has a frequency of 400 Hz and a wavelength of 0.85 m. Find (i) its speed, (ii) its time period and (iii) the distance it travels in 5 s.", a: "(i) v = λν = 0.85 × 400 = 340 m s⁻¹\n(ii) T = 1 ÷ ν = 1 ÷ 400 = 0.0025 s\n(iii) Distance = v × t = 340 × 5 = 1700 m", marks: 3 },
      { q: "Calculate the minimum distance of a reflecting wall from a listener for a distinct echo to be heard when the speed of sound is 340 m s⁻¹. Why is no echo heard in a small room?", a: "The sensation of sound persists for about 0.1 s, so the echo must return after at least 0.1 s.\nTotal distance of to-and-fro travel = 340 × 0.1 = 34 m, so the minimum distance of the wall = 34 ÷ 2 = 17 m.\nIn a small room the walls are nearer than this, so the reflected sound arrives within 0.1 s and merges with the original sound.", marks: 3 },
      { q: "Describe how a sound wave travels through air. Define wavelength, frequency, amplitude and time period, with their SI units, and write the relation between speed, frequency and wavelength.", a: "1. A vibrating object pushes the air particles next to it, producing a compression (high pressure); as it moves back it leaves a rarefaction (low pressure). These alternate and move forward as a longitudinal wave, while each particle only vibrates about its mean position.\n2. Wavelength (λ): distance between two consecutive compressions or rarefactions; unit metre.\n3. Frequency (ν): number of oscillations per second; unit hertz.\n4. Amplitude: maximum displacement of particles from their mean position; unit metre. Time period (T): time for one oscillation, T = 1/ν; unit second.\n5. Speed of the wave v = λν.", marks: 5 },
      { q: "What is SONAR? Explain how it is used to find the depth of the sea, and calculate the depth if the signal returns after 3 s in sea water, where the speed of sound is 1500 m s⁻¹.", a: "1. SONAR (Sound Navigation And Ranging) is a device that uses ultrasonic waves to measure the depth of water and to locate underwater objects.\n2. A transmitter on the ship sends an ultrasonic pulse downward; it is reflected from the seabed and detected by a receiver.\n3. The time t between sending and receiving is noted.\n4. The pulse travels the depth twice, so 2d = v × t and d = v × t ÷ 2.\n5. d = 1500 × 3 ÷ 2 = 2250 m.", marks: 5 },
      {
        q: "Case study: A student notes the frequencies of some sounds: an elephant's call 10 Hz, a flute note 1000 Hz, a dog whistle 25 kHz and a bat's squeak 60 kHz. Take the speed of sound in air as 340 m s⁻¹.\n(i) Which of these is infrasound?\n(ii) Which sounds cannot be heard by a human being?\n(iii) Find the wavelength of the flute note.",
        a: "(i) The elephant's call (10 Hz), since it is below 20 Hz.\n(ii) The elephant's call (below 20 Hz) and the dog whistle and bat's squeak (above 20 kHz), because the human range is 20 Hz to 20 kHz.\n(iii) λ = v ÷ ν = 340 ÷ 1000 = 0.34 m.",
        marks: 4, type: "case"
      }
    ]
  }
,
  "improvement-in-food-resources": {
    mcq: [
      { q: "Pulses such as gram and lentil are the main source of:", options: ["carbohydrates", "fats", "proteins", "vitamin C"], answer: 2, explain: "Cereals give carbohydrates, pulses give proteins and oilseeds give fats.", level: 1 },
      { q: "Which of these is a kharif crop?", options: ["Wheat", "Paddy", "Gram", "Mustard"], answer: 1, explain: "Paddy is sown in the rainy season (June to October). Wheat, gram and mustard are rabi crops.", level: 1 },
      { q: "Which of these is a macronutrient for plants?", options: ["Calcium", "Iron", "Zinc", "Boron"], answer: 0, explain: "The six macronutrients are nitrogen, phosphorus, potassium, calcium, magnesium and sulphur.", level: 1 },
      { q: "Vermi-compost is prepared by using:", options: ["neem leaves", "blue-green algae", "sun hemp", "earthworms"], answer: 3, explain: "Earthworms are used to hasten the decomposition of plant and animal waste into vermi-compost.", level: 1 },
      { q: "Broilers are poultry birds raised for:", options: ["eggs", "milk", "meat", "wool"], answer: 2, explain: "Layers are raised for eggs and broilers for meat.", level: 1 },

      {
        q: "Assertion (A): Mixed cropping reduces the risk of total crop failure.\nReason (R): If one crop is damaged, the other crop grown with it may still give a harvest.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Growing two or more crops together spreads the risk, which is why mixed cropping reduces total loss.", level: 2, keepOrder: true
      },
      {
        q: "Assertion (A): Crop rotation helps to maintain soil fertility.\nReason (R): Crop rotation means growing two or more crops together on the same piece of land.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 2, explain: "A is true. R is false: crop rotation is growing different crops one after another in a planned sequence; growing them together is mixed cropping or intercropping.", level: 2, keepOrder: true
      },
      { q: "Gurmeet mixes the seeds of wheat and gram and sows them together in the same field. This practice is called:", options: ["intercropping", "crop rotation", "green manuring", "mixed cropping"], answer: 3, explain: "Growing two or more crops together without a definite row pattern is mixed cropping.", level: 2 },
      { q: "A godown keeps stored wheat in damp, warm conditions, and the grain is spoilt by insects and fungi. The damp, warm conditions and the insects and fungi are respectively:", options: ["biotic factors; abiotic factors", "abiotic factors; biotic factors", "biotic factors; biotic factors", "abiotic factors; abiotic factors"], answer: 1, explain: "Moisture and temperature are abiotic factors. Insects, rodents and fungi are biotic factors.", level: 2 },
      { q: "A correct pair of micronutrients for plants is:", options: ["nitrogen, phosphorus", "iron, zinc", "calcium, magnesium", "potassium, sulphur"], answer: 1, explain: "Iron, manganese, boron, zinc, copper, molybdenum and chlorine are micronutrients. The other pairs are macronutrients.", level: 2 },

      { q: "Of the 16 nutrients that plants need, the number obtained from the soil and the number of those that are micronutrients are:", options: ["13 and 6", "16 and 7", "9 and 6", "13 and 7"], answer: 3, explain: "Carbon and oxygen come from air and hydrogen and oxygen from water, so 13 nutrients come from soil: 6 macronutrients and 7 micronutrients.", level: 3 },
      { q: "Match: P = decomposed using earthworms; Q = sun hemp ploughed into the soil; R = decomposed animal excreta and plant waste. Which pairing is correct?", options: ["green manure – P, vermi-compost – Q, compost – R", "green manure – Q, vermi-compost – P, compost – R", "green manure – R, vermi-compost – Q, compost – P", "green manure – Q, vermi-compost – R, compost – P"], answer: 1, explain: "Green manure is sun hemp or guar ploughed in; vermi-compost uses earthworms; compost is decomposed animal and plant waste.", level: 3 },
      { q: "Which pair correctly gives a kharif crop followed by a rabi crop?", options: ["Paddy, mustard", "Wheat, cotton", "Gram, maize", "Pigeon pea, soyabean"], answer: 0, explain: "Paddy is kharif and mustard is rabi. In the other pairs the order is reversed or both crops are of the same season.", level: 3 },
      { q: "Which set of practices is typical of organic farming?", options: ["Heavy use of chemical fertilisers and pesticides", "Use of herbicides and growing only GM crops", "Use of manures, neem leaves as bio-pesticide, blue-green algae as bio-fertiliser and crop rotation", "Use of fertilisers for N, P and K and fumigation of the field"], answer: 2, explain: "Organic farming uses little or no chemical fertilisers or pesticides, relying on manures, bio-fertilisers, bio-pesticides and crop rotation.", level: 3 }
    ],
    written: [
      { q: "Name any two weeds found in crop fields.", a: "Xanthium (gokhroo) and Parthenium (gajar ghas).", marks: 1 },
      { q: "What are oilseeds? Give two examples.", a: "Oilseeds are crops grown for the fats (oils) they provide, for example groundnut, mustard, soyabean, sesame and sunflower (any two).", marks: 1 },
      { q: "Differentiate between macronutrients and micronutrients, giving two examples of each.", a: "Macronutrients are the nutrients needed by plants in large amounts (six in number), e.g. nitrogen and potassium.\nMicronutrients are needed in small amounts (seven in number), e.g. iron and zinc.", marks: 2 },
      { q: "Distinguish between manure and fertiliser (any two points).", a: "Manure is made by decomposition of animal excreta and plant waste; it adds organic matter and improves soil structure. A fertiliser is a commercially made chemical source of nutrients like N, P and K.\nFertilisers act quickly but their overuse pollutes water and harms soil fertility, whereas manure supplies nutrients slowly and keeps the soil healthy.", marks: 2 },
      { q: "Describe any three methods used to protect crops from weeds and pests.", a: "1. Pesticides: herbicides for weeds, insecticides for insects and fungicides for fungi, used in controlled amounts.\n2. Use of disease-resistant varieties of crops.\n3. Summer ploughing, which exposes and kills weeds and pests, and mechanical removal of weeds.", marks: 3 },
      { q: "What causes losses of grain during storage? Mention two preventive measures.", a: "Losses are caused by biotic factors (insects, rodents, fungi, mites and bacteria) and abiotic factors (unsuitable moisture and temperature).\nPreventive measures: (1) proper drying and cleaning of grain before storage; (2) fumigation with chemicals to kill pests.", marks: 3 },
      { q: "What is composite fish culture? Why are several species of fish grown together in it?", a: "Composite fish culture is the rearing of five or six fish species together in one pond, such as catla, rohu, mrigal, common carp and grass carp.\nThe species feed in different zones of the pond and so do not compete for food.\nThis makes better use of the pond and increases the total fish yield.", marks: 3 },
      { q: "Explain mixed cropping, intercropping and crop rotation, giving one example and one advantage of each.", a: "1. Mixed cropping: growing two or more crops together on the same land, e.g. wheat + gram. It reduces the risk of total crop failure.\n2. Intercropping: growing two or more crops in a definite row pattern, e.g. alternate rows of soyabean and maize. Crops with different nutrient needs are chosen, so they use soil nutrients well.\n3. Crop rotation: growing different crops in a pre-planned succession on the same land, which helps maintain soil fertility.", marks: 5 },
      { q: "What is organic farming? Describe three types of manure used in it and explain why excessive use of chemical fertilisers is harmful.", a: "1. Organic farming is a farming system with little or no use of chemical fertilisers and pesticides; it relies on manures, bio-fertilisers and bio-pesticides.\n2. Compost: made by decomposition of animal excreta and plant waste.\n3. Vermi-compost: compost prepared with the help of earthworms.\n4. Green manure: plants like sun hemp or guar grown and then ploughed into the soil. (Other organic practices include blue-green algae as bio-fertiliser, neem leaves as bio-pesticide and crop rotation.)\n5. Excess chemical fertilisers pollute water and reduce soil fertility over time.", marks: 5 },
      {
        q: "Case study: Kuldeep has a small farm. He keeps Jersey cows for milk and a few Sahiwal cows, raises poultry birds for eggs and for meat, and also keeps bee boxes of Apis mellifera.\n(i) Which birds does he keep for eggs and which for meat?\n(ii) Why are exotic breeds like Jersey chosen, and why local breeds like Sahiwal?\n(iii) What products does he get from the bees, and why is Apis mellifera used?",
        a: "(i) Layers are kept for eggs and broilers for meat.\n(ii) Exotic breeds such as Jersey are chosen for their long lactation period (more milk); local breeds such as Sahiwal are chosen for their resistance to disease.\n(iii) Honey and wax. The Italian bee Apis mellifera is used because it gives a high honey yield.",
        marks: 4, type: "case"
      }
    ]
  }
});
